   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Why the Work Doesn''t Get Done', 'The existing lessons teach two scheduling techniques. Neither helps if you already know what to do and do not do it — which is the actual problem most people have, and it is not a scheduling problem.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Inside the Mind of a Master Procrastinator', 'Tim Urban''s TED talk on what is actually happening when you put something off — and the harder case nobody talks about. About 14 minutes.', 'https://www.youtube.com/watch?v=arj7oStGLkU', 1,
      array['Explain why deadlines produce work and open-ended goals do not', 'Identify the things in your life with no deadline attached', 'Create real deadlines for work nobody else is chasing'],
      'A calendar full of colour-coded blocks does nothing for the person who opens their laptop, looks at the block that says "write proposal", and opens WhatsApp instead. This lesson is about that gap.

THE MODEL: there is a rational planner, an instant-gratification instinct that wants the easy thing right now, and panic — which only shows up when a deadline is close. Panic is what actually gets most work done, which is why so many people believe they "work well under pressure". They do not work well; they only work at all under pressure.

THE PART THAT MATTERS MOST FOR YOU is the case with NO DEADLINE. Everything with a deadline eventually gets done badly at the last minute. Everything WITHOUT one — building a portfolio, learning a skill, starting the side business, finding better clients — never triggers panic and can be postponed indefinitely. Years of it, invisibly.

Look honestly at what you have been meaning to start. It almost certainly has no deadline and no one waiting on it. That is the whole reason it has not happened, and it is not a character flaw.

WHAT ACTUALLY WORKS, and it is not willpower:

MANUFACTURE THE DEADLINE AND MAKE SOMEONE ELSE AWARE OF IT. Tell a client a date. Book the session. Post that it is coming. An external commitment creates the pressure that self-imposed intentions never do.

MAKE THE FIRST STEP EMBARRASSINGLY SMALL. "Write the proposal" is an invitation to postpone. "Open a document and write the client''s name" is not. Starting is the part that is hard; continuing is much easier, which is why the trick is to make starting trivial.

WORK IN SHORT FIXED BLOCKS. Twenty-five minutes with the phone in another room, then a break. A short block is easier to begin than an open-ended afternoon, and beginning is the whole battle.

SEPARATE FROM THE DISTRACTION PHYSICALLY. Not silenced, not face-down — in another room. Willpower loses to proximity every time.

AND A NOTE FOR ANYONE WORKING ONLINE FROM HOME HERE: without a boss, an office or fixed hours, almost nothing in freelance work has a real deadline until a client sets one. That is exactly the dangerous case in this talk. The freelancers who build something are the ones who invent their own deadlines and tell somebody about them.',
      'Write down the one thing you have been meaning to start for months and have not. Then give it three things it currently lacks: a date, a person who knows about that date, and a first step small enough to do in ten minutes. Do the ten-minute step now, before you close this lesson. That is the entire exercise, and it is the part people skip.',
      '[{"question":"Why do long-term goals get postponed indefinitely while urgent work gets done?","options":["Without a deadline there is no panic, and panic is what forces most people to start","Long-term goals are usually less important","Urgent work is more interesting","People forget their long-term goals"],"correct_index":0},{"question":"What is the most effective fix for something you keep postponing?","options":["Give it a real deadline that another person knows about","Schedule a longer block of time for it","Wait until you feel motivated","Break it into a detailed twenty-step plan"],"correct_index":0}]'::jsonb),
    (v_m1, 'Procrastination Is About Feelings, Not Time', 'TED-Ed on the research behind procrastination — why it happens even when it makes you feel worse, and what actually interrupts it. Under 6 minutes.', 'https://www.youtube.com/watch?v=FWTNMzK9vG4', 2,
      array['Explain procrastination as avoiding a feeling rather than avoiding work', 'Name the emotion attached to a task you are avoiding', 'Use self-forgiveness and task redesign instead of self-criticism'],
      'This is the piece that makes the previous lesson usable, and it contradicts almost everything productivity advice tells you.

PROCRASTINATION IS NOT A TIME-MANAGEMENT PROBLEM. It is avoidance of a NEGATIVE FEELING attached to the task — boredom, anxiety, self-doubt, resentment, or fear of doing it badly. The brain trades a small immediate relief for a larger later cost, which is why you can procrastinate on something you genuinely want to do.

WHICH IS WHY BETTER PLANNING DOES NOT FIX IT. A more detailed schedule does not change how the task feels. This is why people buy planners and still do not start.

THE FIRST MOVE IS TO NAME THE FEELING. Sit with the task and ask what specifically is unpleasant about it. In real work it is usually one of:
- I do not know how to start, so it feels like exposure
- I am afraid it will not be good enough
- It is genuinely boring
- I resent having agreed to it

Each has a different fix. Not knowing how to start needs a smaller first step or a question asked. Fear of it being bad needs permission to produce a bad first version. Boredom needs a shorter block or a reward attached. Resentment is information about your workload or your pricing, and it is worth listening to rather than pushing through.

SELF-CRITICISM MAKES IT WORSE, and this is the most counter-intuitive finding: people who forgive themselves for procrastinating procrastinate LESS next time. Beating yourself up adds another negative feeling to the task, which makes avoiding it more attractive. If you have lost a week, the useful response is "that happened, what is the ten-minute step now" — not a lecture.

AND REDESIGN THE TASK rather than trying harder at it. Make the first step smaller, remove a decision, do the unpleasant part first while your energy is high, or attach it to something you like. Changing how a task feels beats trying to out-discipline how it feels.

ONE HONEST CAVEAT: persistent inability to start, alongside low mood or exhaustion that does not lift, can be about more than a task. That is worth talking to someone about, and it is not a productivity problem to solve with a technique.',
      'Pick something you have been avoiding this week and write one sentence naming the feeling — not the task. "I am avoiding this because I am afraid the client will think it is amateur", or "because I do not know where to start". Then choose the matching fix and change the task itself: make step one smaller, give yourself permission to do a bad first draft, or shorten the block. Do it once and notice whether naming it changed anything.',
      '[{"question":"What is procrastination actually avoiding?","options":["A negative feeling attached to the task, not the work itself","The time the task will take","The consequences of failure","Tasks that are genuinely unimportant"],"correct_index":0},{"question":"What does the research say about being hard on yourself for procrastinating?","options":["It makes it worse — self-forgiveness reduces future procrastination","It is the most effective corrective","It has no measurable effect either way","It works only for short deadlines"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Where the Time Goes, and Getting Into Flow', 'Two things the scheduling techniques assume you already know: what your time is actually spent on, and how to reach the state where work goes quickly and well.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'You Have More Time Than You Think', 'Laura Vanderkam''s TED talk on what time studies actually show — and why "I do not have time" usually means something else. About 12 minutes.', 'https://www.youtube.com/watch?v=n3kNlFMXslo', 1,
      array['Track where your hours actually go rather than where you assume', 'Reframe "I do not have time" as a statement about priorities', 'Schedule what matters first instead of hoping for leftover time'],
      'The central move here is uncomfortable and useful: "I do not have time" almost always means "that is not a priority for me". Try saying the second version out loud for a week and notice which sentences you are unwilling to finish.

THE ARITHMETIC: a week is 168 hours. Work forty and sleep eight a night and there are still around seventy-two left. Most people cannot say where those went, which is the actual problem — not scarcity, but invisibility.

TRACK BEFORE YOU OPTIMISE. Write down what you do in half-hour chunks for one week. It is tedious and it is the only way to see the truth. Almost everyone finds several hours they had no idea about, usually scrolling, and usually more than they would have guessed by a factor of two or three.

TIME IS FOUND, NOT MADE. When a genuine emergency happens — a burst pipe, a sick relative — hours appear from somewhere. Those hours existed before the emergency; they were being spent on things that mattered less. That is the whole argument.

PUT THE IMPORTANT THINGS IN FIRST. Decide what has to happen this week and place it before the week fills with other people''s requests. Whatever is left over absorbs the rest. Waiting for spare time to appear is how the portfolio never gets built.

A REALISTIC ADJUSTMENT FOR THIS AUDIENCE, because the talk is written for people with a lot of control over their day: if you are commuting two hours in Nairobi traffic, sharing a room, working around power cuts, or supporting family alongside your own work, your seventy-two hours are genuinely smaller than the talk implies. The method still holds — track first, then place what matters before the rest — but be honest about what is actually available. A plan built on hours you do not have fails and then feels like a personal failure, which it is not.

AND PROTECT SMALL BLOCKS RATHER THAN WAITING FOR BIG ONES. Two focused hours a week, kept every week, finishes a portfolio in a few months. Waiting for a free Saturday finishes nothing, because the free Saturday does not come.',
      'Track your time in half-hour blocks for three days — a note on your phone is enough. Then total three categories honestly: paid work, learning or building something of your own, and screen time that was not either. Most people find the third is larger than expected. Now take one thing you have been saying you have no time for, and put it in next week''s calendar BEFORE anything else fills the space.',
      '[{"question":"What does \"I do not have time for that\" usually mean?","options":["It is not a priority for me right now","The task is genuinely impossible to fit in","The task will take longer than expected","Other people are taking up the hours"],"correct_index":0},{"question":"What is the first step before trying to manage your time better?","options":["Track where the hours actually go for a week","Buy or set up a better planning system","Cut out one obvious time-waster","Wake up earlier"],"correct_index":0}]'::jsonb),
    (v_m2, 'Getting Into Flow', 'TED-Ed on the flow state — the conditions that produce it, and why most working setups make it impossible. About 5 minutes.', 'https://www.youtube.com/watch?v=0rIjFCNay2Q', 2,
      array['Name the conditions that make flow possible', 'Match task difficulty to your current skill so work absorbs you', 'Remove the interruptions that make deep work impossible'],
      'Flow is the state where work goes quickly and well and time disappears. It is not luck; it has conditions, and most people''s working setup breaks every one of them.

WHAT IT NEEDS:

A CLEAR GOAL FOR THIS SESSION. Not "work on the website" but "finish the contact page". Vagueness prevents flow, because part of your attention stays busy deciding what to do.

DIFFICULTY MATCHED TO SKILL. Too easy is boring, too hard is anxious; flow lives in the narrow band just beyond comfortable. If you cannot get absorbed, the task is usually mismatched — break a hard one into a piece you can actually do, or add difficulty to a dull one.

IMMEDIATE FEEDBACK, so you can tell whether it is working without stopping to check.

NO INTERRUPTIONS. This is where it fails for almost everyone. Flow takes roughly fifteen to twenty minutes to enter and one notification to destroy, and re-entering starts the clock again. A morning of five interruptions is a morning with no deep work in it at all, regardless of hours spent at the desk.

SO THE PRACTICAL SETUP: phone in another room, notifications off — actually off, not silenced — one task, a defined block of time, and everyone who might interrupt told when you will be available. Ninety minutes of that is worth a whole scattered day.

FOR REMOTE WORK SPECIFICALLY, the biggest destroyer is being permanently reachable. Being expected to answer WhatsApp or Slack instantly means never being more than a few minutes from an interruption, which means never entering flow. Agree response times explicitly with clients — "I check messages at 11 and 4" — and most will not mind at all. The people who reply instantly to everything are not the ones producing the best work; they are the ones who never get an hour to themselves.

AND WORK WITH YOUR REAL ENERGY, not a schedule from a book. Most people have two or three genuinely sharp hours a day. Find yours and give them to the hardest thing rather than to email. In a household where the power or the quiet is unreliable, this matters more, not less — protect the hours you can actually control.',
      'Set up one ninety-minute block this week with all four conditions: one specific goal you could tick off, a task at the edge of your ability, phone in another room, and everyone told you are unavailable. Work only on that. Afterwards write down how long it took to get absorbed and what broke it if anything did. Then do it again on the same day next week — the point is a repeatable slot, not one good session.',
      '[{"question":"Why does a vague goal prevent flow?","options":["Part of your attention stays busy deciding what to do","Vague goals take longer to complete","It makes the task too easy","Flow requires a written plan"],"correct_index":0},{"question":"What does a single notification cost you?","options":["The flow state, which takes fifteen to twenty minutes to re-enter","About a minute, the time to read it","Nothing, if you do not reply","Only your place in the task"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

